"""Offline, dependency-free report UI; molecule depictions live beside the HTML."""
import json


def render(report):
    # JSON is embedded as data, never interpolated into executable JavaScript/HTML.
    encoded = json.dumps(report, ensure_ascii=False, allow_nan=False).replace('<', '\\u003c').replace('&', '\\u0026')
    return TEMPLATE.replace('__REPORT_DATA__', encoded)


TEMPLATE = r'''<!doctype html>
<html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>MolNova · Iteration landscape</title>
<style>
:root{font:15px system-ui,sans-serif;color:#203443;background:#f3f6f8}*{box-sizing:border-box}body{margin:0}header{background:#123545;color:white;padding:32px max(24px,calc((100vw - 1400px)/2));border-bottom:5px solid #58b4a7}header small{color:#9ce0d5;letter-spacing:.13em}h1{font-size:30px;margin:10px 0}h2{font-size:21px;margin:0 0 12px}h3{font-size:16px;margin:10px 0}main{max-width:1450px;margin:24px auto;padding:0 24px}.panel{background:white;border:1px solid #dae4e9;border-radius:12px;padding:22px;margin-bottom:20px}.muted{color:#627984;font-size:13px;line-height:1.6}.toolbar{display:flex;flex-wrap:wrap;gap:12px;align-items:center;margin:16px 0}select,button{font:inherit;border:1px solid #b6cad3;border-radius:6px;padding:7px 10px;background:white;color:#203443}button{cursor:pointer}.badges{display:flex;gap:24px;flex-wrap:wrap;margin-top:18px}.badge b{display:block;font-size:25px}.badge span{font-size:12px;color:#b9d7df}.mapgrid{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:20px}#map{width:100%;height:520px;touch-action:none;background:#fbfcfd;border:1px solid #dce6eb;border-radius:8px;cursor:crosshair}#detail{background:#f3f7f9;border-radius:8px;padding:16px;overflow-wrap:anywhere}#detail img{width:100%;background:white}#detail p{margin:8px 0}#legend{display:flex;gap:7px;flex-wrap:wrap}#legend label{padding:4px 8px;border-radius:20px;background:#f1f5f7;font-size:12px;cursor:pointer}.dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:5px}.metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(340px,1fr));gap:16px}.chart{border:1px solid #e1e9ed;border-radius:8px;padding:12px}.chart svg{width:100%;display:block}table{border-collapse:collapse;width:100%;font-size:13px}th,td{text-align:left;padding:10px;border-bottom:1px solid #e2eaee;white-space:nowrap}th{color:#607580}.scroll{overflow:auto}.compare{display:grid;grid-template-columns:1fr 1fr;gap:20px}.core{max-width:320px;width:100%}.fragments{display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:8px}.fragment{background:#f7f9fb;border:1px solid #e2eaee;border-radius:6px;padding:8px;overflow-wrap:anywhere;font-size:11px}.fragment img{width:100%;background:white}.notice{padding:12px;background:#fff5dd;border-radius:6px;color:#745522}footer{font-size:12px;color:#627984;padding:0 0 28px}a{color:#13756f}@media(max-width:850px){.mapgrid,.compare{grid-template-columns:1fr}.metrics{grid-template-columns:1fr}#map{height:400px}main{padding:0 12px}.panel{padding:16px}}
</style>
<header><small>MOLNOVA / ITERATION LANDSCAPE</small><h1>화합물군의 변화</h1><div id="subtitle"></div><div class="badges" id="badges"></div></header>
<main>
<section class="panel"><h2>화학 공간 지도</h2><p class="muted" id="projection"></p>
<div class="toolbar"><label>색상 <select id="color"><option value="iteration">Iteration</option></select></label><label>비교 집단 <select id="cohort"><option value="all">전체 생성군 + 기준 화합물</option><option value="selected">Druglike 통과 기록이 있는 군</option><option value="primg_gbsa_scored">primg_gbsa 점수가 있는 군</option></select></label><button id="reset">지도 초기화</button><span class="muted">휠: 확대 · 드래그: 이동 · 점 클릭: 분자 구조</span></div>
<div id="legend"></div><p class="muted" id="shown"></p><div class="mapgrid"><canvas id="map" aria-label="Interactive molecular chemical-space scatter plot"></canvas><aside id="detail"><b>화합물을 선택하세요</b><p class="muted">점 하나가 원본 분자 하나입니다. 기준 화합물은 검은색 테두리, 지도에 포함된 iteration별 Prime 상위군은 큰 테두리로 표시합니다.</p></aside></div>
<p class="muted">지도는 최대 2,000개를 iteration별로 균형 있게 표본 추출합니다. 2D 거리는 구조 유사성의 근사 표현이며 결합력이나 진화 계보를 의미하지 않습니다. 좌표계는 첫 비퇴화 생성군의 Morgan fingerprint PCA로 고정됩니다.</p></section>
<section class="panel"><h2>물성 · 계산 점수 분포</h2><p class="muted">아래 통계는 지도 표본이 아닌 해당 집단의 전체 DB 행을 사용합니다. 선: 최솟값–최댓값 · 상자: 25–75% · 중앙선: 중앙값. 각 행에 유효 값 수(n)를 표시합니다. Glide / GBSA / FEP는 각각 별도 점수이며 작은 값이 우선입니다. 계산된 부분집합 사이의 비교에는 선별 효과가 포함됩니다.</p><div class="metrics" id="metrics"></div>
<div class="toolbar"><label>상세 히스토그램 <select id="histMetric"></select></label></div><div id="histograms"></div></section>
<section class="panel"><h2>치환기 구조 비교</h2><p class="muted">각 iteration의 저장된 scaffold와 결합 위치를 사용합니다. 빈도는 점수와 무관한 최대 200개 표본 중 분해에 성공한 분자를 기준으로 계산합니다. 대칭 scaffold의 위치는 기존 분해 규칙을 따르며 유일한 화학적 위치 배정을 보장하지 않습니다. 서로 다른 scaffold의 R 번호는 대응하지 않습니다.</p>
<div class="toolbar"><label>이전 군 <select id="leftIteration"></select></label><label>비교 군 <select id="rightIteration"></select></label></div><p id="comparisonNote"></p><div class="compare"><div id="left"></div><div id="right"></div></div></section>
<section class="panel"><h2>Iteration 현황</h2><div class="scroll"><table><thead><tr><th>Iteration</th><th>전체</th><th>Druglike 통과</th><th>선별 미기록</th><th>Glide n</th><th>Prime n</th><th>구조 다양성¹</th><th>직전 Prime 상위군 유사도²</th></tr></thead><tbody id="overview"></tbody></table></div><p class="muted">¹ 1 − 평균 쌍별 Tanimoto, 점수와 무관한 최대 200개 표본. 높을수록 표본 내 다양성이 큽니다. ² 바로 직전 iteration의 유한 Prime 상위군에 대한 각 표본의 최대 Tanimoto 중앙값. 부모 관계를 뜻하지 않습니다. 선별 기록·점수·scaffold가 없으면 미기록으로 표시합니다.</p></section>
<footer id="footer"></footer></main>
<script type="application/json" id="report-data">__REPORT_DATA__</script>
<script>
'use strict';
const D=JSON.parse(document.getElementById('report-data').textContent), $=id=>document.getElementById(id);
const palette=['#267e8c','#d9784c','#7864a1','#62a76b','#c49c38','#ca6688','#4876bc','#9a7555'];
const tint=i=>i===0?'#354b57':palette[(i-1)%palette.length], fmt=v=>v===null||v===undefined?'n/a':Number(v).toFixed(3), label=i=>`iter${String(i).padStart(2,'0')}`;
function node(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e}
function option(select,value,text){const e=node('option',text);e.value=value;select.append(e)}
$('subtitle').textContent=`${D.project} · ${label(D.through_iteration)}까지 · ${D.event} · ${D.generated_at}`;
for(const [v,t] of [[D.population_n,'DB 화합물'],[D.iterations.length,'Iteration'],[D.map_n,'지도 표본']]){const e=node('div',undefined,'badge');e.append(node('b',v.toLocaleString()),node('span',t));$('badges').append(e)}
$('projection').textContent=`${D.projection.method} · ${D.projection.status||`고정 축 학습: ${label(D.projection.trained_through)} / ${D.projection.training_count}개`}${D.projection.explained_variance_ratio?' · 초기 학습군의 2D 설명분산 '+(100*D.projection.explained_variance_ratio.reduce((a,b)=>a+b,0)).toFixed(1)+'%':''} · 유효하지 않은 지도 표본: ${D.invalid_sample_ids.length}`;
for(const [key,text] of Object.entries(D.metrics)){option($('color'),key,text);option($('histMetric'),key,text)}
const visible=new Set(D.iterations.map(x=>x.iteration));
for(const item of D.iterations){const l=node('label'),check=node('input');check.type='checkbox';check.checked=true;const dot=node('span',undefined,'dot');dot.style.background=tint(item.iteration);l.append(check,dot,document.createTextNode(label(item.iteration)));check.onchange=()=>{check.checked?visible.add(item.iteration):visible.delete(item.iteration);redraw()};$('legend').append(l);for(const id of ['leftIteration','rightIteration'])option($(id),item.iteration,label(item.iteration))}
function cohort(){return $('cohort').value}
function points(){return D.points.filter(p=>visible.has(p.iteration)&&(cohort()==='all'||(cohort()==='selected'?p.selected===1:p.values.primg_gbsa_score!==null)))}
const canvas=$('map'),ctx=canvas.getContext('2d');let zoom=1,panX=0,panY=0,drawn=[];
function drawMap(){const rect=canvas.getBoundingClientRect(),w=rect.width,h=rect.height,dpr=window.devicePixelRatio||1;canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);const all=D.points;
let xmin=Infinity,xmax=-Infinity,ymin=Infinity,ymax=-Infinity;for(const p of all){xmin=Math.min(xmin,p.x);xmax=Math.max(xmax,p.x);ymin=Math.min(ymin,p.y);ymax=Math.max(ymax,p.y)}if(!all.length){xmin=ymin=-1;xmax=ymax=1}const dx=xmax-xmin||1,dy=ymax-ymin||1;
ctx.strokeStyle='#e2eaf0';ctx.lineWidth=1;for(let i=1;i<5;i++){ctx.beginPath();ctx.moveTo(i*w/5,0);ctx.lineTo(i*w/5,h);ctx.stroke();ctx.beginPath();ctx.moveTo(0,i*h/5);ctx.lineTo(w,i*h/5);ctx.stroke()}
const ps=points(),key=$('color').value;let lo=Infinity,hi=-Infinity;for(const p of all){const v=p.values[key];if(v!==null&&v!==undefined){lo=Math.min(lo,v);hi=Math.max(hi,v)}}
drawn=[];for(const p of ps){const x=(28+(p.x-xmin)/dx*(w-56)-w/2)*zoom+w/2+panX,y=(h-28-(p.y-ymin)/dy*(h-56)-h/2)*zoom+h/2+panY;let color=tint(p.iteration);if(key!=='iteration'){const v=p.values[key];if(v===null||v===undefined)color='#b4bfc6';else{const t=(v-lo)/(hi-lo||1);color=`hsl(${235-220*t},65%,48%)`}}ctx.globalAlpha=.72;ctx.fillStyle=color;ctx.beginPath();ctx.arc(x,y,p.elite?5:3.2,0,Math.PI*2);ctx.fill();if(p.elite||p.iteration===0){ctx.globalAlpha=1;ctx.strokeStyle=p.iteration===0?'#14232f':color;ctx.lineWidth=1.3;ctx.beginPath();ctx.arc(x,y,p.elite?7:5,0,Math.PI*2);ctx.stroke()}drawn.push({p,x,y})}ctx.globalAlpha=1;ctx.fillStyle='#637b88';ctx.font='12px system-ui';ctx.fillText('PC1 →',w-55,h-8);ctx.fillText('PC2 ↑',8,18);$('shown').textContent=`표시 ${ps.length} / 지도 표본 ${D.map_n}개`+(key!=='iteration'?` · ${D.metrics[key]}: 파랑 ${fmt(lo===Infinity?null:lo)} → 빨강 ${fmt(hi===-Infinity?null:hi)} · 회색: 미계산`:'')}
function detail(p){const box=$('detail');box.replaceChildren(node('b',`CMPID_${p.id} · ${label(p.iteration)}`));if(p.image){const img=node('img');img.src=p.image;img.alt=p.smiles;box.append(img)}box.append(node('p',p.name),node('p',p.smiles,'muted'),node('p',`상태: ${p.state}`,'muted'));for(const [key,text] of Object.entries(D.metrics))box.append(node('p',`${text}: ${fmt(p.values[key])}`));}
let drag=null,moved=false;canvas.onpointerdown=e=>{drag={x:e.clientX,y:e.clientY};moved=false;canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dx)+Math.abs(dy)>2)moved=true;panX+=dx;panY+=dy;drag={x:e.clientX,y:e.clientY};drawMap()};canvas.onpointerup=e=>{drag=null;if(moved)return;const r=canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;const nearest=drawn.map(p=>({...p,d:(x-p.x)**2+(y-p.y)**2})).sort((a,b)=>a.d-b.d)[0];if(nearest&&nearest.d<144)detail(nearest.p)};canvas.onpointercancel=()=>drag=null;canvas.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(.3,Math.min(30,zoom*(e.deltaY>0?.9:1.1)));drawMap()},{passive:false});$('reset').onclick=()=>{zoom=1;panX=panY=0;drawMap()};$('color').onchange=drawMap;
const NS='http://www.w3.org/2000/svg';function svgEl(tag,attrs,text){const e=document.createElementNS(NS,tag);for(const [k,v]of Object.entries(attrs))e.setAttribute(k,v);if(text!==undefined)e.textContent=text;return e}
function chart(metric,hist=false){const items=D.iterations.filter(x=>visible.has(x.iteration)),svg=svgEl('svg',{viewBox:`0 0 500 ${50+items.length*34}`,role:'img','aria-label':D.metrics[metric]}),[lo,hi]=D.bounds[metric],px=v=>92+(v-lo)/(hi-lo)*300;svg.append(svgEl('line',{x1:92,y1:20,x2:392,y2:20,stroke:'#b1c4cd'}));for(let k=0;k<=4;k++){const v=lo+(hi-lo)*k/4;svg.append(svgEl('text',{x:px(v),y:12,'text-anchor':'middle',fill:'#627984','font-size':10},v.toFixed(1)))}items.forEach((it,j)=>{const y=42+j*34,s=it.cohorts[cohort()].metrics[metric],color=tint(it.iteration);svg.append(svgEl('text',{x:0,y:y+4,fill:color,'font-size':12},label(it.iteration)),svgEl('text',{x:405,y:y+4,fill:'#627984','font-size':11},`n=${s.n}`));if(!s.n){svg.append(svgEl('text',{x:100,y:y+4,fill:'#8c9ca5','font-size':11},'미계산 / 미기록'));return}if(hist){const max=Math.max(...s.hist,1);s.hist.forEach((n,k)=>svg.append(svgEl('rect',{x:92+15*k,y:y-20*n/max,width:14,height:20*n/max,fill:color})));}else{svg.append(svgEl('line',{x1:px(s.min),y1:y,x2:px(s.max),y2:y,stroke:color}),svgEl('rect',{x:px(s.q1),y:y-8,width:Math.max(1,px(s.q3)-px(s.q1)),height:16,fill:color,opacity:.35}),svgEl('line',{x1:px(s.median),y1:y-9,x2:px(s.median),y2:y+9,stroke:color,'stroke-width':3}));}});return svg}
function drawDistributions(){$('metrics').replaceChildren();for(const [key,text]of Object.entries(D.metrics)){const card=node('div',undefined,'chart');card.append(node('h3',text),chart(key));$('metrics').append(card)}$('histograms').replaceChildren(chart($('histMetric').value,true))}
$('histMetric').onchange=()=>{$('histograms').replaceChildren(chart($('histMetric').value,true))};$('cohort').onchange=redraw;
function groupCard(id,it){const target=$(id),s=it.substituents;target.replaceChildren(node('h3',label(it.iteration)),node('p',`${s.matched_n}/${s.sample_n} 표본 분해 · scaffold ${s.scaffold_key||'미기록'}`,'muted'));if(!s.scaffold){target.append(node('p',s.status,'muted'));return}if(s.image){const img=node('img',undefined,'core');img.src=s.image;img.alt=s.scaffold;target.append(img)}target.append(node('p',s.scaffold,'muted'));for(const site of s.sites){target.append(node('h3',`R${site.label} · 치환기 ${site.unique_n}종 (상위 6종)`));const grid=node('div',undefined,'fragments');for(const part of site.top){const card=node('div',undefined,'fragment');if(part.image){const img=node('img');img.src=part.image;img.alt=part.smiles;card.append(img)}card.append(node('b',`${part.count}개 · ${(100*part.fraction).toFixed(1)}%`),node('p',part.smiles));grid.append(card)}target.append(grid)}}
function compare(){if(!D.iterations.length)return;const left=D.iterations.find(x=>x.iteration===Number($('leftIteration').value)),right=D.iterations.find(x=>x.iteration===Number($('rightIteration').value));groupCard('left',left);groupCard('right',right);const same=left.substituents.scaffold_key&&left.substituents.scaffold_key===right.substituents.scaffold_key;$('comparisonNote').textContent=same?'동일한 저장 scaffold입니다. 같은 R 번호의 치환기 빈도를 비교할 수 있습니다.':'scaffold가 다르거나 미기록입니다. R 번호를 직접 대응시키지 마세요.';$('comparisonNote').className=same?'muted':'notice'}
$('rightIteration').selectedIndex=Math.max(0,D.iterations.length-1);$('leftIteration').selectedIndex=Math.max(0,D.iterations.length-2);$('leftIteration').onchange=compare;$('rightIteration').onchange=compare;
for(const it of D.iterations){const tr=node('tr'),d=it.diversity;for(const v of [label(it.iteration),it.n,it.cohorts.selected.n,it.selection_unknown,it.cohorts.all.metrics.docking_score.n,it.cohorts.all.metrics.primg_gbsa_score.n,`${fmt(d.internal_diversity)} (n=${d.sample_n})`,`${fmt(d.previous_elite_similarity_median)} (elite n=${d.previous_elite_n})`])tr.append(node('td',v));$('overview').append(tr)}
$('footer').textContent='읽기 전용 DB 스냅샷 · 계산/선별 상태를 변경하지 않습니다. 분포는 DB에 저장된 유한 값만 사용하며 누락값은 대체하지 않습니다. HTML과 molecules 폴더를 함께 보관하세요.';
function redraw(){drawMap();drawDistributions()}window.addEventListener('resize',drawMap);redraw();compare();
</script></html>'''
